	secretAssignmentPattern = regexp.MustCompile(`(?i)\b([a-z0-9_.-]*(?:secret|token|api[_-]?key|password)[a-z0-9_.-]*)\s*[:=]\s*("[^"]*"|'[^']*'|[^,\s]+)`)
