func splitCheckpointAuditSentences(value string) []string {
	value = strings.TrimSpace(value)
	if value == "" {
		return nil
	}
	var parts []string
	for _, part := range strings.FieldsFunc(value, func(r rune) bool {
		return r == ';' || r == '!' || r == '?'
	}) {
